ALTER TABLE public.subscriptions ADD COLUMN IF NOT EXISTS is_test boolean NOT NULL DEFAULT false;
UPDATE public.subscriptions SET is_test=true WHERE is_test=false;
CREATE OR REPLACE FUNCTION public.finalize_test_signup_payment(p_user_id uuid,p_email text,p_transaction_id text,p_provider_subscription_id text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $function$ DECLARE v_intent public.payment_intents%rowtype; v_payment_id uuid; v_subscription_id uuid; v_next_billing_date timestamptz; BEGIN SELECT * INTO v_intent FROM public.payment_intents WHERE provider_transaction_id=p_transaction_id AND status='pending' AND is_test=true AND lower(email)=lower(p_email) FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Valid pending test payment intent not found'; END IF; v_next_billing_date:=date_trunc('month',now())+interval '1 month'+interval '6 days'; INSERT INTO public.payments(user_id,amount_mur,status,peach_payment_id,paid_at,currency,processor_response,fees_covered_amount_mur,reconciliation_status,is_test) VALUES(p_user_id,v_intent.amount_mur,'pending',v_intent.provider_transaction_id,null,v_intent.currency,jsonb_build_object('simulated',true,'payment_intent_id',v_intent.id),0,'pending',true) ON CONFLICT(peach_payment_id) WHERE peach_payment_id IS NOT NULL DO NOTHING RETURNING id INTO v_payment_id; IF v_payment_id IS NULL THEN SELECT id INTO v_payment_id FROM public.payments WHERE peach_payment_id=v_intent.provider_transaction_id LIMIT 1; END IF; PERFORM public.allocate_payment_funds(v_payment_id,p_user_id,v_intent.amount_mur); UPDATE public.payments SET status='success',paid_at=now(),reconciliation_status='success',gateway_response=jsonb_build_object('simulated',true,'payment_intent_id',v_intent.id,'provider_subscription_id',p_provider_subscription_id) WHERE id=v_payment_id; SELECT id INTO v_subscription_id FROM public.subscriptions WHERE user_id=p_user_id ORDER BY created_at DESC LIMIT 1; IF v_subscription_id IS NULL THEN INSERT INTO public.subscriptions(user_id,amount_mur,status,peach_subscription_id,covers_fees,start_date,next_billing_date,is_test) VALUES(p_user_id,v_intent.amount_mur,'active',p_provider_subscription_id,v_intent.covers_fees,now(),v_next_billing_date,true) RETURNING id INTO v_subscription_id; ELSE UPDATE public.subscriptions SET status='active',amount_mur=v_intent.amount_mur,peach_subscription_id=coalesce(p_provider_subscription_id,peach_subscription_id),covers_fees=v_intent.covers_fees,start_date=coalesce(start_date,now()),next_billing_date=v_next_billing_date,is_test=true,updated_at=now() WHERE id=v_subscription_id; END IF; UPDATE public.payments SET subscription_id=v_subscription_id WHERE id=v_payment_id; UPDATE public.payment_intents SET status='completed',completed_at=now(),provider_subscription_id=p_provider_subscription_id WHERE id=v_intent.id; RETURN v_payment_id; END; $function$;